const md = new MarkdownIt({ html: true });
const l10n = join(import.meta.dirname, "..", "..", "l10n");
let bad = 0;
for (const locale of readdirSync(l10n)) {
  let po: string;
  try {
    po = readFileSync(join(l10n, locale, "docs.api.po"), "utf8");
  } catch {
    continue;
  }
  for (const entry of parsePo(po)) {
    if (entry.obsolete || !entry.msgstr || entry.msgctxt !== "docs.api:prose") continue;
    const html = md.render(escapeBareHtmlTags(entry.msgstr));
    try {
      parse(`<div>${html}</div>`, {
        onError: (e) => {
          throw e;
        },
      });
    } catch (error) {
      bad++;
      console.log(`${locale}: ${(error as Error).message}\n  ${entry.msgstr.slice(0, 200)}`);
    }
  }
}
console.log(`bad: ${bad}`);
